// 对齐 unicom_gateway.dart sendSmsCode()（L60-95）与 unicom_crypto.dart（PKCS#1 v1.5，BT=0x02）：
// 19 字段顺序、_urlSafe（仅转义 + 与 =，L167-168）、_timestamp（本地时间 14 位，L192-197）、
// androidId = _uuidHex().substring(8, 24)（32 位 hex 的 [8,24) 段，L79）逐行对齐源码。
function urlSafe(s) {
  return s.split('+').join('%2B').split('=').join('%3D');
}
function pad2(n) {
  return n < 10 ? '0' + n : '' + n;
}
var d = new Date();
var ts = '' + d.getFullYear() + pad2(d.getMonth() + 1) + pad2(d.getDate()) +
  pad2(d.getHours()) + pad2(d.getMinutes()) + pad2(d.getSeconds());
var androidId = fn.randomHex(32).substring(8, 24);
var ua = uaPrefix + ' unicom{version:android@10.0100,desmobile:' + phone +
  '};devicetype{deviceBrand:OnePlus,deviceModel:LE2100};{yw_code:}';
var mobileEnc = urlSafe(fn.rsaPkcs1(pub, phone, '02'));
var body = [
  'isFirstInstall=1',
  'resultToken=',
  'provinceCode=051',
  'cityCode=520',
  'deviceOS=android13',
  'mobile=' + mobileEnc,
  'netWay=Wifi',
  'loginCodeLen=6',
  'version=' + urlSafe('android@10.0600'),
  'deviceCode=' + deviceId,
  'deviceId=' + deviceId,
  'pip=192.168.2.125',
  'keyVersion=',
  'send_flag=',
  'provinceChanel=general',
  'appId=' + appId,
  'deviceModel=V1936A',
  'androidId=' + androidId,
  'deviceBrand=',
  'timestamp=' + ts
].join('&');
return { body: body, ua: ua, androidId: androidId };

// 对齐 unicom_gateway.dart L86-90 与 _messageOf（L172-178）：
// code 为 ''/'0'/'0000' 即成功；非 JSON / 缺字段响应经 extract optional+default 已归一为 ''，
// 等价源码 jsonDecode 失败回退 {} 与 (data['code'] ?? '') 语义（非 JSON → code='' → 成功）。
// err 取 msg → message → desc → resultMsg 首个非空，否则回退。
var err = '';
if (msg) {
  err = msg;
} else if (message) {
  err = message;
} else if (desc) {
  err = desc;
} else if (resultMsg) {
  err = resultMsg;
} else {
  err = '验证码下发失败';
}
var ok = code === '' || code === '0' || code === '0000';
return { ok: ok, err: err };

// 对齐 unicom_gateway.dart login()（L98-118）：18 字段（无 deviceCode，仅 deviceId）；
// mobile 重新加密（PKCS#1 随机填充，每次密文不同）、version 与发码不同（android@10.0100）、
// password = urlSafe(rsa(smsCode))、androidId 每请求新生成、时间戳每请求新取。
function urlSafe(s) {
  return s.split('+').join('%2B').split('=').join('%3D');
}
function pad2(n) {
  return n < 10 ? '0' + n : '' + n;
}
var d = new Date();
var ts = '' + d.getFullYear() + pad2(d.getMonth() + 1) + pad2(d.getDate()) +
  pad2(d.getHours()) + pad2(d.getMinutes()) + pad2(d.getSeconds());
var androidId = fn.randomHex(32).substring(8, 24);
var ua = uaPrefix + ' unicom{version:android@10.0100,desmobile:' + phone +
  '};devicetype{deviceBrand:OnePlus,deviceModel:LE2100};{yw_code:}';
var body = [
  'isFirstInstall=1',
  'simCount=1',
  'yw_code=',
  'loginStyle=0',
  'isRemberPwd=true',
  'deviceOS=android13',
  'mobile=' + urlSafe(fn.rsaPkcs1(pub, phone, '02')),
  'netWay=Wifi',
  'version=' + urlSafe('android@10.0100'),
  'deviceId=' + deviceId,
  'password=' + urlSafe(fn.rsaPkcs1(pub, smsCode, '02')),
  'keyVersion=',
  'provinceChanel=general',
  'appId=' + appId,
  'deviceModel=V1936A',
  'androidId=' + androidId,
  'deviceBrand=',
  'timestamp=' + ts
].join('&');
return { body: body, ua: ua, androidId: androidId };

// 对齐 unicom_gateway.dart L122-136：token_online 或 ecs_token 任一非空即成功；
// 失败消息 _messageOf（msg → message → desc → resultMsg 首个非空，
// 回退「登录失败，请检查短信验证码」）。token 原样透传给 output。
var err = '';
if (msg) {
  err = msg;
} else if (message) {
  err = message;
} else if (desc) {
  err = desc;
} else if (resultMsg) {
  err = resultMsg;
} else {
  err = '登录失败，请检查短信验证码';
}
var ok = token_online !== '' || ecs_token !== '';
return { ok: ok, err: err, token_online: token_online, ecs_token: ecs_token };
